<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">City watch</span><h1>Civic issues</h1><p>Approved concerns raised by citizens across Nagpur.</p><a class="pill pill-dark" href="<?=url('issues/create')?>">Raise an issue ↗</a></header><form class="filter-bar wrap" method="get"><label>Category<select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"<?=selected($_GET['category']??'',$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Locality<input name="locality" value="<?=e($_GET['locality']??'')?>"></label><button class="pill pill-dark">Filter</button></form><div class="wrap issue-grid list-grid"><?php foreach($issues as $i=>$issue):?><article class="issue-card <?=$i===0?'featured':''?>"><div class="card-meta"><span><?=e($issue['category'])?></span><span class="status"><?=e(str_replace('_',' ',$issue['progress_status']))?></span></div><div><h3><?=e($issue['title'])?></h3><p><?=e(mb_strimwidth($issue['description'],0,190,'…'))?></p></div><div class="card-bottom"><span><?=e($issue['supports'])?> supporters</span><a class="arrow" href="<?=url('issues/'.$issue['slug'])?>">↗</a></div></article><?php endforeach;?><?php if(!$issues):?><div class="empty-state">No matching approved issues.</div><?php endif;?></div></div>
